<?php
// Read filter SQL generated by crb_filters_test.js --sql; isolated DB only.
define('BASEPATH',__DIR__.'/../system/');
define('APPPATH',__DIR__.'/../application/');
define('ENVIRONMENT','development');
function is_php($v){return version_compare(PHP_VERSION,$v,'>=');}
function log_message($level,$message){}
function show_error($message){throw new RuntimeException($message);}
require BASEPATH.'database/DB.php';
$db=DB(array('hostname'=>'127.0.0.1','port'=>3407,'username'=>'root','password'=>'','database'=>'charge_framework_test',
    'dbdriver'=>'mysqli','pconnect'=>false,'db_debug'=>false,'char_set'=>'utf8mb4','dbcollat'=>'utf8mb4_unicode_ci'),true);
$filters=json_decode(file_get_contents(__DIR__.'/../.local/crb-filter-test.json'),true,512,JSON_THROW_ON_ERROR);
function verify($ok,$message){if(!$ok)throw new RuntimeException($message);}
verify($db->database==='charge_framework_test','Unsafe test DB');
if (!$db->field_exists('branch','loan')) verify($db->query('ALTER TABLE loan ADD branch INT NULL')!==false,'Test branch schema');
$db->trans_begin();
try {
    // Full legacy test schema is installed by the existing integration suite.
    $cases=array(
        990040=>array('CLOSED',100,0,100,'individual'),
        990041=>array('ACTIVE',100,0,100,'individual'),
        990042=>array('CLOSED',99.99,0,100,'individual'),
        990043=>array('CLOSED',100,0.01,100,'individual'),
        990044=>array('WRITTEN_OFF',100,0,100,'individual'),
        990045=>array('CLOSED',100,0,100,'group'),
        990046=>array('CLOSED',0,0,0,'individual'),
        990047=>array('CLOSED',200,0,100,'individual'),
        990048=>array('CLOSED',100,0,100,'individual')
    );
    foreach($cases as $id=>$case) {
        verify($db->insert('loan',array('loan_id'=>$id,'loan_status'=>$case[0],'disbursed'=>'Yes','customer_type'=>$case[4],
            'loan_product'=>$id===990048?3:2,'branch'=>$id===990048?8:7,'loan_date'=>$id===990048?'2025-05-11':'2026-05-11')),'Loan fixture');
        if ($id===990046) continue;
        verify($db->insert('payement_schedules',array('loan_id'=>$id,'payment_number'=>1,'amount'=>$case[3],
            'paid_amount'=>$case[1],'total_late_charge'=>$case[2])),'Schedule fixture');
        if ($id===990047) $db->insert('payement_schedules',array('loan_id'=>$id,'payment_number'=>2,'amount'=>100,'paid_amount'=>0));
    }
    foreach($filters as $name=>$filter) {
        $result=$db->query('SELECT loan.loan_id FROM loan WHERE loan.loan_id BETWEEN 990040 AND 990048 AND '.$filter['where'].' ORDER BY loan.loan_id',$filter['params']);
        verify($result!==false,'CRB filter SQL failed: '.json_encode($db->error()));
        $ids=array_map(function($row){return (int)$row->loan_id;},$result->result());
        verify($ids===($name==='paid'?array(990040,990041,990048):array(990040,990041)),'CRB status/product/branch/date selection failed: '.json_encode($ids));
    }
    echo "PASS: CRB paid-up SQL includes settled active/closed loans and excludes unpaid cents, late charges, written-off loans, groups, empty schedules and overpayment masking.\n";
} finally {$db->trans_rollback();}
